script:
html { scroll-behavior: smooth; }
::selection { background: var(--a3c47e91-5b28-4f06-9d13-7e2a8c4b6002, #1A1915); color: var(--a3c47e91-5b28-4f06-9d13-7e2a8c4b6001, #FBFAF7); }
body { -webkit-font-smoothing: antialiased; }

/* reveal, armed only when motion is allowed */
html.td-motion .td-rise { opacity: 0; transform: translateY(12px); }
html.td-motion .td-rise.td-in {
  opacity: 1; transform: none;
  transition: opacity 0.9s cubic-bezier(0.22, 1, 0.36, 1),
    transform 0.9s cubic-bezier(0.22, 1, 0.36, 1);
}
html.td-motion .td-d1.td-in { transition-delay: 0.12s; }
html.td-motion .td-d2.td-in { transition-delay: 0.24s; }

/* corner ticks on figures */
.td-frame { position: relative; }
.td-frame::before, .td-frame::after {
  color: var(--a3c47e91-5b28-4f06-9d13-7e2a8c4b6003, #75736B); content: "+"; font-family: "Fragment Mono", monospace;
  font-size: 13px; line-height: 1; position: absolute; z-index: 2;
}
.td-frame::before { left: -5px; top: -7px; }
.td-frame::after { bottom: -7px; right: -5px; }

/* the map that never got replaced */
.td-x {
  background-image:
    linear-gradient(to top right, transparent calc(50% - 0.5px),
      var(--a3c47e91-5b28-4f06-9d13-7e2a8c4b6004, #D8D6CE) calc(50% - 0.5px), var(--a3c47e91-5b28-4f06-9d13-7e2a8c4b6004, #D8D6CE) calc(50% + 0.5px),
      transparent calc(50% + 0.5px)),
    linear-gradient(to bottom right, transparent calc(50% - 0.5px),
      var(--a3c47e91-5b28-4f06-9d13-7e2a8c4b6004, #D8D6CE) calc(50% - 0.5px), var(--a3c47e91-5b28-4f06-9d13-7e2a8c4b6004, #D8D6CE) calc(50% + 0.5px),
      transparent calc(50% + 0.5px));
}

/* quiet interactions */
.td-link { transition: color 0.18s ease; }
.td-link:hover { color: var(--a3c47e91-5b28-4f06-9d13-7e2a8c4b6006, #3D647C); }
.td-btn { transition: opacity 0.18s ease; }
.td-btn:hover { opacity: 0.85; }
.td-card { transition: transform 0.3s cubic-bezier(0.22, 1, 0.36, 1); }
.td-card:hover { transform: translateY(-2px); }
.td-row { transition: background-color 0.2s ease; }
.td-row:hover { background-color: var(--a3c47e91-5b28-4f06-9d13-7e2a8c4b6005, #F2F0E9); }

img { filter: saturate(0.92); }
@media (prefers-color-scheme: dark) {
  img { filter: saturate(0.88) brightness(0.88); }
}

a:focus-visible { outline: 1px solid var(--a3c47e91-5b28-4f06-9d13-7e2a8c4b6006, #3D647C); outline-offset: 3px; }
